<?php
// Listado público de encuestas: mantiene el diseño celeste original y consulta MariaDB.
require __DIR__.'/common.php';
$q=trim($_GET['q']??''); $cat=(int)($_GET['categoria']??0);
$sql="SELECT e.*,COUNT(DISTINCT en.id) respuestas,GROUP_CONCAT(DISTINCT c.nombre SEPARATOR ', ') categorias FROM encuestas e LEFT JOIN envios_encuesta en ON en.encuesta_id=e.id LEFT JOIN encuesta_categoria ec ON ec.encuesta_id=e.id LEFT JOIN categorias c ON c.id=ec.categoria_id WHERE e.estado='publicada' AND (e.publico='publico' OR ?=1)";
$params=[logged_in()?1:0]; if($q!==''){$sql.=' AND (e.titulo LIKE ? OR e.descripcion LIKE ? OR c.nombre LIKE ? OR c.grupo LIKE ?)';for($i=0;$i<4;$i++)$params[]="%$q%";} if($cat>0){$sql.=' AND EXISTS(SELECT 1 FROM encuesta_categoria x WHERE x.encuesta_id=e.id AND x.categoria_id=?)';$params[]=$cat;} elseif($cat===-1){$sql.=' AND NOT EXISTS(SELECT 1 FROM encuesta_categoria x WHERE x.encuesta_id=e.id)';} $sql.=' GROUP BY e.id ORDER BY e.creado_en DESC';$st=$pdo->prepare($sql);$st->execute($params);$surveys=$st->fetchAll();
site_start('Hospital de Clínicas | Encuestas','info','Encuestas del Hospital de Clínicas','Consulte las encuestas disponibles y seleccione la que desea responder.',['index.html'=>'Inicio','portal_usuario.html'=>'Documentación','login.html'=>'Personal','#faq'=>'FAQ','#ayuda'=>'Ayuda']);
?>
<section class="container py-5"><div class="card shadow"><div class="card-body"><form method="get" action="index.php" class="row g-3"><input type="hidden" name="p" value="encuestas"><div class="col-lg-6"><input type="search" name="q" value="<?=h($q)?>" class="form-control" placeholder="Buscar por nombre o palabra clave..."></div><div class="col-lg-4"><select class="form-select" name="categoria"><option value="0">Todas las especialidades</option><option value="-1" <?=$cat===-1?'selected':''?>>General</option><?php foreach(categories_grouped($pdo) as $group=>$items): ?><optgroup label="<?=h($group)?>"><?php foreach($items as $c): ?><option value="<?=$c['id']?>" <?=$cat===(int)$c['id']?'selected':''?>><?=h($c['nombre'])?></option><?php endforeach; ?></optgroup><?php endforeach; ?></select></div><div class="col-lg-2 d-grid"><button class="btn text-white" style="background:linear-gradient(135deg,#0dcaf0,#0aa2c0);border-color:#0aa2c0">Buscar</button></div></form></div></div></section>
<section class="container pb-5"><div class="row g-4"><?php if(!$surveys): ?><div class="col-12"><div class="alert alert-light border text-center">No hay encuestas publicadas para mostrar.</div></div><?php endif; ?><?php foreach($surveys as $s): ?><div class="col-lg-6"><div class="card shadow h-100"><div class="card-body"><span class="badge bg-info badge-categoria text-dark"><?=h($s['categorias']?:'General')?></span><h4 class="mt-3"><?=h($s['titulo'])?></h4><p class="text-muted"><?=h($s['descripcion'])?></p><p class="mb-1"><strong>Servicio:</strong> <?=h($s['categorias']?:'General')?></p><p><strong>Respuestas recibidas:</strong> <?= (int)$s['respuestas']?></p><a href="index.php?p=responder&id=<?=$s['id']?>" class="btn text-white" style="background:linear-gradient(135deg,#0dcaf0,#0aa2c0);border-color:#0aa2c0">Responder</a></div></div></div><?php endforeach; ?></div></section>
<section id="faq" class="container pb-4"><div class="row justify-content-center"><div class="col-lg-8"><div class="card shadow"><div class="card-header bg-info text-white"><h3 class="mb-0">Preguntas frecuentes</h3></div><div class="card-body"><div class="accordion" id="faqEncuestas"><div class="accordion-item"><h2 class="accordion-header"><button class="accordion-button" data-bs-toggle="collapse" data-bs-target="#eFaq1">¿Las respuestas son anónimas?</button></h2><div id="eFaq1" class="accordion-collapse collapse show"><div class="accordion-body">Sí. Las respuestas se guardan sin nombre ni cédula.</div></div></div><div class="accordion-item"><h2 class="accordion-header"><button class="accordion-button collapsed" data-bs-toggle="collapse" data-bs-target="#eFaq2">¿Quién puede responder encuestas para personal?</button></h2><div id="eFaq2" class="accordion-collapse collapse"><div class="accordion-body">Las encuestas privadas requieren iniciar sesión con una cuenta autorizada.</div></div></div></div></div></div></div></div></section><section id="ayuda" class="container mb-8 pb-5" style="--bs-primary:#0aa2c0;margin-bottom:3rem!important"><style>#ayuda .btn-outline-primary{color:#0aa2c0;background:#fff;border:1px solid #0aa2c0;transition:0.2s} #ayuda .btn-outline-primary:hover{color:#fff;background:linear-gradient(135deg,#0dcaf0,#0aa2c0);border-color:#0aa2c0});border-color:#0aa2c0}#supportModal .btn-primary{color:#fff;background:linear-gradient(135deg,#0dcaf0,#0aa2c0);border-color:#0aa2c0}</style><div class="row justify-content-center"><div class="col-lg-6"><div class="card shadow h-100"><div class="card-header text-white" style="background:linear-gradient(135deg,#0dcaf0,#0aa2c0)"><h3 class="mb-0">¿Necesita ayuda?</h3></div><div class="card-body"><p>Si tiene dificultades para responder una encuesta, envíe una consulta al equipo administrador.</p><?php support_button(); ?></div></div></div></div></section><?php support_modal(); site_end(); ?>
